<?php
namespace App\Http\Controllers;
use App\Models\Package; use Illuminate\Http\Request;
class PackageController extends Controller { public function index(){return view('packages.index',['packages'=>Package::latest()->get()]);} public function store(Request $r){$d=$r->validate(['name'=>'required|max:100','price'=>'required|integer|min:0','normal_profile'=>'required|max:120','normal_speed'=>'nullable|max:50','burst_enabled'=>'nullable|boolean','burst_limit'=>'nullable|max:50','burst_threshold'=>'nullable|max:50','priority'=>'required|integer|min:1|max:8','fup_enabled'=>'nullable|boolean','fup_limit_bytes'=>'nullable|integer|min:0','fup_speed_after'=>'nullable|max:50']);Package::create($d);return back()->with('success','Paket tersimpan.');} public function update(Request $r,Package $package){$d=$r->validate(['name'=>'required|max:100','price'=>'required|integer|min:0','normal_profile'=>'required|max:120','normal_speed'=>'nullable|max:50','burst_enabled'=>'nullable|boolean','burst_limit'=>'nullable|max:50','burst_threshold'=>'nullable|max:50','priority'=>'required|integer|min:1|max:8','fup_enabled'=>'nullable|boolean','fup_limit_bytes'=>'nullable|integer|min:0','fup_speed_after'=>'nullable|max:50']);$package->update($d);return back()->with('success','Paket diperbarui.');} public function destroy(Package $package){$package->delete();return back()->with('success','Paket dihapus.');}}
